-- Room-object logic bindings, taken from the shipped assets.
--
-- furniture_definitions.logic decides which server-side behaviour a furni gets. It shipped holding
-- the raw Arcturus interaction_type ('vendingmachine', 'bed', 'crackable', ...) or 'none', and
-- almost none of those strings is a registered Vortex logic: 53 782 of 55 279 definitions resolved
-- to nothing and fell through to the family default. Silently -- the furni simply never did its
-- thing.
--
-- The authority is the asset, not the dump: every <classname>.nitro embeds a JSON part whose
-- logicType names the logic the client binds. Regenerate with
-- tools/catalog_converter/scan_asset_logic.py, which reads the whole furni pack.
--
-- ONE RULE MATTERS HERE: a definition whose current logic is already a registered Vortex logic is
-- left alone. The client's names are not a superset of ours -- it calls a gate
-- 'furniture_multistate' because Flash derives blocking from the visualization, while Vortex
-- resolves walkability server-side. Blindly taking the asset value would have overwritten 744
-- working definitions, including 375 gates (which would stop blocking), 55 rollers, and wired
-- furni, whose Vortex logic names deliberately mirror Arcturus.
--
-- SECOND RULE, and the reason 1 937 definitions keep an unregistered Arcturus name: the client has
-- no logic for behaviour that is purely server-side. A vending machine, a bed, a teleport and a
-- pressure plate all look plain to it, so their assets say `furniture_basic` or
-- `furniture_multistate`. Taking that would replace the only surviving record that the furni is
-- meant to do something -- 598 vending machines, 145 teleports, 140 switches, 136 pressure plates,
-- 80 beds -- with a name that says "ordinary furni". Behaviour would not change (both resolve to
-- the family default) but the to-do list would be erased. So a plain asset logic never overwrites a
-- meaningful interaction_type; it only replaces 'none'.
--
-- Names that are not registered are still written: they are the truth about what the furni is, they
-- resolve to the correct family default at runtime, and the provider's warning then names precisely
-- which behaviour is missing. That warning is the to-do list.
--
-- Statements are name-scoped and idempotent; a trimmed furnidata just matches fewer rows.
--
-- Logic names of features M0 removed (wired, game tiles, crackables...) are still written: they are
-- no longer registered, so they resolve to the family default like any other unregistered name.

-- 31967 definitions
UPDATE `furniture_definitions`
   SET `logic` = 'furniture_multistate'
 WHERE `name` IN (
    '01_caterbody', '01_caterbody', '01_caterhead', '01_caterhead',
    '01_dragonlamp_skream', '01_dragonlamp_skream', '01_dragonlamp_skream', '02_caterbody',
